import AgentWarMapPortrait from "@/components/agentmap/AgentWarMapPortrait";
import AgentWarMapWide from "@/components/agentmap/AgentWarMapWide";

/**
 * 内部预览页：并排比较两套「多 Agent 协作作战地图」在 Hero 中的落位。
 * - 方案①：加宽右栏（竖向地图）
 * - 方案②：整宽背景（横向地图）
 * 仅用于决策选型，定稿后删除本路由。访问 /preview/maps
 */
export const metadata = {
  title: "作战地图选型预览",
  robots: { index: false, follow: false },
};

function Legend() {
  return (
    <div className="surface mt-6 grid gap-5 p-6 text-sm sm:grid-cols-2 lg:grid-cols-4">
      <div>
        <p className="mb-3 font-semibold text-foreground">节点</p>
        <ul className="space-y-2 text-muted-foreground">
          <li className="flex items-center gap-2">
            <span className="inline-block h-3 w-3 rounded-sm bg-[var(--primary)]/40 ring-1 ring-[var(--primary)]" />
            你（领导者）· 主色 + 冠标
          </li>
          <li className="flex items-center gap-2">
            <span className="inline-block h-3 w-3 rounded-sm bg-[var(--card)] ring-1 ring-[var(--primary)]" />
            CEO 编排枢纽
          </li>
          <li className="flex items-center gap-2">
            <span className="inline-block h-3 w-3 rounded-sm bg-[var(--card)] ring-1 ring-[var(--border)]" />
            队员卡（身份色侧条）
          </li>
        </ul>
      </div>
      <div>
        <p className="mb-3 font-semibold text-foreground">状态</p>
        <ul className="space-y-2 text-muted-foreground">
          <li className="flex items-center gap-2">
            <span className="inline-block h-2.5 w-2.5 rounded-full bg-[var(--primary)]" />
            运行中（环旋转）
          </li>
          <li className="flex items-center gap-2">
            <span className="inline-block h-2.5 w-2.5 rounded-full bg-[var(--success)]" />
            已完成（✓）
          </li>
          <li className="flex items-center gap-2">
            <span className="inline-block h-2.5 w-2.5 rounded-full bg-[var(--warning)]" />
            阻塞（! 闪烁）
          </li>
          <li className="flex items-center gap-2">
            <span className="inline-block h-2.5 w-2.5 rounded-full bg-[var(--muted-foreground)]" />
            待运行（虚线）
          </li>
        </ul>
      </div>
      <div>
        <p className="mb-3 font-semibold text-foreground">连线</p>
        <ul className="space-y-2 text-muted-foreground">
          <li>实线 + 流动短划 · 任务流向（DAG）</li>
          <li>双向虚线 + 点 · A2A 协作 / 辩论 / 互审</li>
          <li className="text-[var(--warning)]">琥珀闪烁虚线 · 阻塞升级给你</li>
        </ul>
      </div>
      <div>
        <p className="mb-3 font-semibold text-foreground">其它</p>
        <ul className="space-y-2 text-muted-foreground">
          <li>队员卡右下角印记 · MCP 工具（Web/DB/Files/Code）</li>
          <li>虚线圆角框 · 共享工作区</li>
          <li>波次标签 · WaveScheduler 调度</li>
        </ul>
      </div>
    </div>
  );
}

export default function MapsPreviewPage() {
  return (
    <main className="min-h-screen bg-background text-foreground">
      <div className="container-x py-12">
        <p className="eyebrow">
          <span className="inline-block h-1.5 w-1.5 rounded-full bg-primary" />
          内部选型预览 · 定稿后删除
        </p>
        <h1 className="mt-4 text-3xl font-bold tracking-tight sm:text-4xl">
          多 Agent 协作作战地图 · 两版对比
        </h1>
        <p className="mt-3 max-w-3xl text-muted-foreground">
          同一份「新产品上市调研」协作，两种 Hero 落位。注意动效（流动短划、状态环、token
          游走、阻塞闪烁）在系统「减弱动效」偏好下会自动停用。
        </p>
        <Legend />
      </div>

      {/* ── 方案① 加宽右栏（竖向） ── */}
      <section className="border-t border-border/60 bg-[color-mix(in_oklab,var(--primary),transparent_97%)]">
        <div className="container-x py-12">
          <div className="mb-6 flex items-baseline gap-3">
            <span className="rounded-full bg-primary px-3 py-1 text-sm font-bold text-primary-foreground">
              方案①
            </span>
            <h2 className="text-xl font-semibold">加宽右栏 · 竖向地图（左文右图）</h2>
          </div>
          <div className="grid items-center gap-10 lg:grid-cols-[0.82fr_1.18fr]">
            <div className="max-w-xl">
              <p className="eyebrow">
                <span className="inline-block h-1.5 w-1.5 rounded-full bg-primary" />
                协作智能平台
              </p>
              <h3 className="mt-5 text-4xl font-bold leading-[1.1] tracking-tight sm:text-5xl">
                <span className="text-gradient">协作，</span>
                <br />
                是更高级的智能
              </h3>
              <p className="mt-6 text-lg leading-relaxed text-muted-foreground">
                一句需求，CEO 主 Agent 自动组建团队，按依赖关系分波次推进——
                串行、并行、辩论、互审，全程可见。
              </p>
              <div className="mt-8 flex flex-wrap gap-3">
                <span className="btn btn-primary">下载客户端</span>
                <span className="btn btn-ghost">看团队如何协作</span>
              </div>
            </div>
            <div className="w-full lg:justify-self-end">
              <div className="surface mx-auto w-full max-w-[600px] p-5 backdrop-blur-md sm:p-6">
                <div className="mb-3 flex items-center justify-between gap-3">
                  <p className="eyebrow">
                    <span className="inline-block h-1.5 w-1.5 rounded-full bg-primary" />
                    一次协作 · 实时作战图
                  </p>
                  <span className="shrink-0 text-sm text-muted-foreground">
                    8 队员 · 3 波次
                  </span>
                </div>
                <AgentWarMapPortrait />
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* ── 方案② 整宽背景（横向） ── */}
      <section className="border-t border-border/60">
        <div className="container-x py-12">
          <div className="mb-6 flex items-baseline gap-3">
            <span className="rounded-full bg-primary px-3 py-1 text-sm font-bold text-primary-foreground">
              方案②
            </span>
            <h2 className="text-xl font-semibold">整宽地图 · 横向系统全景（图为主角）</h2>
          </div>
          <div className="mx-auto max-w-3xl text-center">
            <h3 className="text-4xl font-bold leading-[1.1] tracking-tight sm:text-5xl">
              <span className="text-gradient">协作，</span>是更高级的智能
            </h3>
            <p className="mx-auto mt-5 max-w-2xl text-lg leading-relaxed text-muted-foreground">
              不是一个助手分饰多角，而是一支真正分工的团队——下面就是一次协作的全景。
            </p>
            <div className="mt-7 flex flex-wrap justify-center gap-3">
              <span className="btn btn-primary">下载客户端</span>
              <span className="btn btn-ghost">看团队如何协作</span>
            </div>
          </div>
          <div className="surface mt-10 w-full p-5 backdrop-blur-md sm:p-7">
            <AgentWarMapWide />
          </div>
        </div>
      </section>
    </main>
  );
}
