import {
  AGENTS,
  AgentChip,
  CommEdge,
  EscalationEdge,
  FlowEdge,
  HubNode,
  MapDefs,
  SharedWorkspace,
  TokenDot,
  WaveTag,
  YouNode,
} from "./shared";

/**
 * 方案① —— 竖向「多 Agent 协作作战地图」，适配加宽后的 Hero 右栏。
 * 自上而下：你 → CEO 编排 → 共享工作区内三波团队协作（A2A 辩论/互审、阻塞升级、MCP 工具印记）
 * → CEO 综合 → 回到你审阅。工具以每个队员卡右下角的「工具印记」体现。
 */
export default function AgentWarMapPortrait() {
  const P = "pm";
  return (
    <svg
      viewBox="0 0 680 736"
      className="h-auto w-full"
      role="img"
      aria-label="多 Agent 协作作战地图（竖向）：你下达目标，CEO 主 Agent 用 delegate 定义 DAG 组团；共享工作区内分三波协作——波次1 市场检索/竞品采集/用户访谈并行，波次2 数据分析/用户画像依赖，波次3 方案正反辩论并经评审互审；各 Agent 经 MCP 调用工具（卡片右下角印记），用户访谈遇阻 escalate 升级给你，最终 CEO 综合裁决回到你审阅"
      style={{ fontFamily: "inherit" }}
    >
      <MapDefs idPrefix={P} />

      {/* 共享工作区（包裹三波次） */}
      <SharedWorkspace x={24} y={200} w={632} h={320} />
      <WaveTag x={40} y={228} text="波次 1 · 并行" anchor="start" />
      <WaveTag x={40} y={326} text="波次 2 · 依赖" anchor="start" />
      <WaveTag x={40} y={424} text="波次 3 · 辩论 · 互审" anchor="start" />

      {/* ── 任务流向（DAG） ── */}
      <FlowEdge idPrefix={P} d="M340 72 L340 96" />
      <FlowEdge idPrefix={P} d="M190 128 L255 128" />
      {/* CEO → 波次1（委派） */}
      <FlowEdge idPrefix={P} d="M330 160 C 220 195, 150 218, 135 236" />
      <FlowEdge idPrefix={P} d="M340 160 L340 238" label="委派" />
      <FlowEdge idPrefix={P} d="M350 160 C 460 195, 540 218, 545 236" />
      {/* 波次1 → 波次2（注入） */}
      <FlowEdge idPrefix={P} d="M140 282 C 165 305, 195 325, 213 336" />
      <FlowEdge idPrefix={P} d="M335 282 C 300 308, 245 325, 220 336" label="注入" />
      <FlowEdge idPrefix={P} d="M540 282 C 515 305, 478 325, 458 336" />
      {/* 波次2 → 波次3 */}
      <FlowEdge idPrefix={P} d="M210 380 C 180 405, 150 425, 135 432" />
      <FlowEdge idPrefix={P} d="M220 380 C 255 405, 318 425, 338 432" />
      <FlowEdge idPrefix={P} d="M450 380 C 415 405, 358 425, 342 432" />
      <FlowEdge idPrefix={P} d="M460 380 C 490 405, 540 425, 545 432" />
      {/* 波次3 → CEO 综合 */}
      <FlowEdge idPrefix={P} d="M135 478 C 200 515, 300 548, 332 556" />
      <FlowEdge idPrefix={P} d="M340 478 L340 556" label="综合" />
      <FlowEdge idPrefix={P} d="M545 478 C 480 515, 380 548, 348 556" />
      <FlowEdge idPrefix={P} d="M340 620 L340 660" />

      {/* ── A2A 协作通信（辩论 / 互审） ── */}
      <CommEdge idPrefix={P} d="M230 456 L245 456" />
      <CommEdge idPrefix={P} d="M435 456 L450 456" />

      {/* ── 阻塞升级（worker → 你） ── */}
      <EscalationEdge idPrefix={P} d="M548 238 C 612 165, 600 58, 392 50" />
      <text
        x={628}
        y={150}
        textAnchor="end"
        fontSize={10.5}
        fontWeight={600}
        fill="var(--warning)"
      >
        escalate 升级
      </text>

      {/* ── 游走产物 token（reduced-motion 下隐藏） ── */}
      <TokenDot path="M340 72 L340 96" dur={2.2} color="var(--primary)" />
      <TokenDot
        path="M340 160 L340 238"
        dur={2.8}
        delay={0.5}
        color="var(--primary)"
      />
      <TokenDot
        path="M340 478 L340 556"
        dur={3}
        delay={1}
        color="var(--primary)"
      />
      <TokenDot
        path="M340 620 L340 660"
        dur={2.6}
        delay={1.4}
        color="var(--primary)"
      />

      {/* ── 节点 ── */}
      <YouNode x={290} y={16} w={100} h={56} sub="下达目标" />
      <HubNode x={40} y={110} w={150} h={36} title="跨会话记忆" />
      <HubNode
        x={255}
        y={96}
        w={170}
        h={64}
        title="CEO 主 Agent"
        sub="delegate · DAG · replan"
      />

      <AgentChip x={40} y={238} w={190} h={44} agent={AGENTS.market} wave={1} />
      <AgentChip x={245} y={238} w={190} h={44} agent={AGENTS.comp} wave={1} />
      <AgentChip
        x={450}
        y={238}
        w={190}
        h={44}
        agent={AGENTS.interview}
        wave={1}
      />
      <AgentChip x={120} y={336} w={190} h={44} agent={AGENTS.data} wave={2} />
      <AgentChip x={360} y={336} w={190} h={44} agent={AGENTS.persona} wave={2} />
      <AgentChip x={40} y={434} w={190} h={44} agent={AGENTS.pro} wave={3} />
      <AgentChip x={245} y={434} w={190} h={44} agent={AGENTS.con} wave={3} />
      <AgentChip x={450} y={434} w={190} h={44} agent={AGENTS.review} wave={3} />

      <HubNode
        x={255}
        y={556}
        w={170}
        h={64}
        title="CEO 综合"
        sub="裁决 · 汇报"
      />
      <YouNode x={290} y={660} w={100} h={56} sub="审阅 · 决策" />
    </svg>
  );
}
